# Package hooks ----------------------------------------------------------------
#
# Not generated by fusen: keep this file registered in dev/config_fusen.yaml
# (fusen::register_files_to_config("R/zzz.R")), otherwise
# fusen::inflate(clean = TRUE) may delete it.

# Package options and their defaults. Users can set them before or after
# library(mintyr); existing values are never overwritten.
.mintyr_options <- list(
  mintyr.quiet = FALSE   # TRUE silences the startup message
)

.onLoad <- function(libname, pkgname) {
  op    <- options()
  toset <- !(names(.mintyr_options) %in% names(op))
  if (any(toset)) options(.mintyr_options[toset])
  invisible()
}

.onAttach <- function(libname, pkgname) {
  # Stay silent in scripts, Rscript, knitr / R Markdown, CI and parallel
  # workers, or when the user asked for it.
  if (!interactive() || isTRUE(getOption("mintyr.quiet"))) return(invisible())

  version <- utils::packageVersion(pkgname)
  leaf    <- if (isTRUE(l10n_info()[["UTF-8"]])) "\U0001F33F " else ""

  packageStartupMessage(
    leaf, pkgname, " ", version, " - docs: https://tony2015116.github.io/mintyr/",
    "\nSilence with options(mintyr.quiet = TRUE)."
  )
}
